// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {RewardVault} from "../src/RewardVault.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    RewardVault c;

    function setUp() public {
        c = new RewardVault();
    }

    function _test(uint256 r1, uint256 r2) internal {
        vm.assume(r2 > r1);
        try c.setRewardRate(r1) {} catch { return; }
        try c.setRewardRate(r2) {} catch { return; }
        assertTrue(c.rewardRate() >= r1);
    }

    function testFuzz_test(uint256 r1, uint256 r2) public {
        _test(r1, r2);
    }

    receive() external payable {}
}
